import{_ as l,a0 as d,w as p,s as o,I as i,x as e,a1 as t,A as n,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"用户、组及其它 Linux 特性 | LCTT x X-CMD","titleTemplate":false,"description":"用户、组及其它 Linux 特性 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用户、组及其它 Linux 特性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用户、组及其它 Linux 特性 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20180710 Users, Groups, and Other Linux Beasts","title":"用户、组及其它 Linux 特性","tag":"201812","desc":""},"relativePath":"201812/20180710 Users, Groups, and Other Linux Beasts.md","filePath":"[post].md"}'),u={name:"201812/20180710 Users, Groups, and Other Linux Beasts.md"};function g(h,s,c,k,b,f){const a=d("Link");return p(),o("div",null,[s[26]||(s[26]=i("h1",{id:"用户、组及其它-linux-特性",tabindex:"-1"},[e("用户、组及其它 Linux 特性 "),i("a",{class:"header-anchor",href:"#用户、组及其它-linux-特性","aria-label":"Permalink to “用户、组及其它 Linux 特性”"},"​")],-1)),s[27]||(s[27]=i("blockquote",null,[i("p",null,"Linux 和其他类 Unix 操作系统依赖于用户组，而不是逐个为用户分配权限和特权。一个组就是你想象的那样：一群在某种程度上相关的用户。")],-1)),s[28]||(s[28]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/flamingo-2458782_1920.jpg?itok=_gkzGGx5",alt:""})],-1)),i("p",null,[s[2]||(s[2]=e("到这个阶段，",-1)),t(a,{href:"https://linux.cn/article-10066-1.html"},{default:n(()=>[...s[0]||(s[0]=[e("在看到如何操作目录或文件夹之后",-1)])]),_:1}),s[3]||(s[3]=e("，但在让自己一头扎进文件之前，我们必须重新审视 ",-1)),s[4]||(s[4]=i("em",null,"权限",-1)),s[5]||(s[5]=e("、",-1)),s[6]||(s[6]=i("em",null,"用户",-1)),s[7]||(s[7]=e(" 和 ",-1)),s[8]||(s[8]=i("em",null,"组",-1)),s[9]||(s[9]=e("。幸运的是，",-1)),t(a,{href:"https://www.linux.com/learn/understanding-linux-file-permissions"},{default:n(()=>[...s[1]||(s[1]=[e("有一个网站上已经有了一个优秀而全面的教程，讲到了权限",-1)])]),_:1}),s[10]||(s[10]=e("，所以你应该去立刻阅读它。简而言之，你使用权限来确定谁可以对文件和目录执行操作，以及他们可以对每个文件和目录执行什么操作 —— 从中读取、写入、移动、擦除等等。",-1))]),s[29]||(s[29]=r(`<p>要尝试本教程涵盖的所有内容，你需要在系统上创建新用户。让我们实践起来，为每一个需要借用你电脑的人创建一个用户，我们称之为 <code>guest</code> 账户。</p><p><strong>警告：</strong> 例如，如果你错误地删除了自己的用户和目录，那么创建用户，特别是删除用户以及主目录会严重损坏系统。你可能不想在你日常的工作机中练习，那么请在另一台机器或者虚拟机上练习。无论你是否想要安全地练习，经常备份你的东西总是一个好主意。检查备份是否正常工作，为你自己以后避免很多咬牙切齿的事情。</p><h3 id="一个新用户" tabindex="-1">一个新用户 <a class="header-anchor" href="#一个新用户" aria-label="Permalink to “一个新用户”">​</a></h3><p>你可以使用 <code>useradd</code> 命令来创建一个新用户。使用超级用户或 root 权限运行 <code>useradd</code>，即使用 <code>sudo</code> 或 <code>su</code>，这具体取决于你的系统，你可以：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo useradd -m guest</span></span></code></pre></div><p>然后输入你的密码。或者也可以这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>su -c &quot;useradd -m guest&quot;</span></span></code></pre></div><p>然后输入 root 或超级用户的密码。</p><p>（ <em>为了简洁起见，我们将从现在开始假设你使用 <code>sudo</code> 获得超级用户或 root 权限。</em> ）</p><p>通过使用 <code>-m</code> 参数，<code>useradd</code> 将为新用户创建一个主目录。你可以通过列出 <code>/home/guest</code> 来查看其内容。</p><p>然后你可以使用以下命令来为新用户设置密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo passwd guest</span></span></code></pre></div><p>或者你也可以使用 <code>adduser</code>，这是一个交互式的命令，它会询问你一些问题，包括你要为用户分配的 shell（是的，shell 有不止一种），你希望其主目录在哪里，你希望他们属于哪些组（有关这点稍后会讲到）等等。在运行 <code>adduser</code> 结束时，你可以设置密码。注意，默认情况下，在许多发行版中都没有安装 <code>adduser</code>，但安装了 <code>useradd</code>。</p><p>顺便说一下，你可以使用 <code>userdel</code> 来移除一个用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo userdel -r guest</span></span></code></pre></div><p>使用 <code>-r</code> 选项，<code>userdel</code> 不仅删除了 <code>guest</code> 用户，还删除了他们的主目录和邮件中的条目（如果有的话）。</p><h3 id="主目录中的内容" tabindex="-1">主目录中的内容 <a class="header-anchor" href="#主目录中的内容" aria-label="Permalink to “主目录中的内容”">​</a></h3><p>谈到用户的主目录，它依赖于你所使用的发行版。你可能已经注意到，当你使用 <code>-m</code> 选项时，<code>useradd</code> 使用子目录填充用户的目录，包括音乐、文档和诸如此类的内容以及各种各样的隐藏文件。要查看 <code>guest</code> 主目录中的所有内容，运行 <code>sudo ls -la /home/guest</code>。</p><p>进入新用户目录的内容通常是由 <code>/etc/skel</code> 架构目录确定的。有时它可能是一个不同的目录。要检查正在使用的目录，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>useradd -D</span></span>
<span class="line"><span>GROUP=100</span></span>
<span class="line"><span>HOME=/home</span></span>
<span class="line"><span>INACTIVE=-1</span></span>
<span class="line"><span>EXPIRE=</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span>
<span class="line"><span>SKEL=/etc/skel</span></span>
<span class="line"><span>CREATE_MAIL_SPOOL=no</span></span></code></pre></div><p>这会给你一些额外的有趣信息，但你现在感兴趣的是 <code>SKEL=/etc/skel</code> 这一行，在这种情况下，按照惯例，它指向 <code>/etc/skel/</code>。</p><p>由于 Linux 中的所有东西都是可定制的，因此你可以更改那些放入新创建的用户目录的内容。试试这样做：在 <code>/etc/skel/</code> 中创建一个新目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /etc/skel/Documents</span></span></code></pre></div><p>然后创建一个包含欢迎消息的文件，并将其复制过来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp welcome.txt /etc/skel/Documents</span></span></code></pre></div><p>现在删除 <code>guest</code> 账户:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo userdel -r guest</span></span></code></pre></div><p>再次创建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo useradd -m guest</span></span></code></pre></div><p>嘿！你的 <code>Documents/</code> 目录和 <code>welcome.txt</code> 文件神奇地出现在了 <code>guest</code> 的主目录中。</p><p>你还可以在创建用户时通过编辑 <code>/etc/default/useradd</code> 来修改其他内容。我的看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GROUP=users</span></span>
<span class="line"><span>HOME=/home</span></span>
<span class="line"><span>INACTIVE=-1</span></span>
<span class="line"><span>EXPIRE=</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span>
<span class="line"><span>SKEL=/etc/skel</span></span>
<span class="line"><span>CREATE_MAIL_SPOOL=no</span></span></code></pre></div><p>这些选项大多数都是不言自明的，但让我们仔细看看 <code>GROUP</code> 选项。</p><h3 id="群组心态" tabindex="-1">群组心态 <a class="header-anchor" href="#群组心态" aria-label="Permalink to “群组心态”">​</a></h3><p>Linux 和其他类 Unix 操作系统依赖于用户组，而不是逐个为用户分配权限和特权。一个组就是你想象的那样：一群在某种程度上相关的用户。在你的系统上可能有一组允许使用打印机的用户，他们属于 <code>lp</code>（即 “<em>line printer</em>”）组。传统上 <code>wheel</code> 组的成员是唯一可以通过使用 <code>su</code> 成为超级用户或 root 的成员。<code>network</code> 用户组可以启动或关闭网络。还有许多诸如此类的。</p><p>不同的发行版有不同的组，具有相同或相似名称的组具有不同的权限，这也取决于你使用的发行版。因此，如果你在前一段中读到的内容与你系统中的内容不匹配，不要感到惊讶。</p><p>不管怎样，要查看系统中有哪些组，你可以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>getent group</span></span></code></pre></div><p><code>getent</code> 命令列出了某些系统数据库的内容。</p><p>要查找当前用户所属的组，尝试：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>groups</span></span></code></pre></div><p>当你使用 <code>useradd</code> 创建新用户时，除非你另行指定，否则用户将只属于一个组：他们自己。<code>guest</code> 用户属于 <code>guest</code> 组。组使用户有权管理自己的东西，仅此而已。</p><p>你可以使用 <code>groupadd</code> 命令创建新组，然后添加用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo groupadd photos</span></span></code></pre></div><p>例如，这将创建 <code>photos</code> 组。下一次，我们将使用它来构建一个共享目录，该组的所有成员都可以读取和写入，我们将更多地了解权限和特权。敬请关注！</p><hr>`,46)),i("p",null,[s[12]||(s[12]=e("via: ",-1)),t(a,{href:"https://www.linux.com/learn/intro-to-linux/2018/7/users-groups-and-other-linux-beasts"},{default:n(()=>[...s[11]||(s[11]=[e("https://www.linux.com/learn/intro-to-linux/2018/7/users-groups-and-other-linux-beasts",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=e("作者：",-1)),t(a,{href:"https://www.linux.com/users/bro66"},{default:n(()=>[...s[13]||(s[13]=[e("Paul Brown",-1)])]),_:1}),s[18]||(s[18]=e(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[14]||(s[14]=[e("lujun9972",-1)])]),_:1}),s[19]||(s[19]=e(" 译者：",-1)),t(a,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[15]||(s[15]=[e("MjSeven",-1)])]),_:1}),s[20]||(s[20]=e(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[23]||(s[23]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:n(()=>[...s[22]||(s[22]=[e("Linux中国",-1)])]),_:1}),s[25]||(s[25]=e(" 荣誉推出",-1))])])}const y=l(u,[["render",g]]);export{C as __pageData,y as default};
